//   "agencias": [
//     { "nombre": "Hyundai Norte", "url": "https://www.google.com/maps?q=-2.120310,-79.909841" },
//     { "nombre": "Hyundai Sur", "url": "https://www.google.com/maps?q=-2.195321,-79.888903" }
//   ]
// ]

function getLatLngFromUrl(url) {
  const match = url.match(/@?(-?\d+\.\d+),\s*(-?\d+\.\d+)/);
  if (!match) throw new Error("No se pudo obtener lat/lon del link de Google Maps");
  return { lat: parseFloat(match[1]), lon: parseFloat(match[2]) };
}

function haversineDistance(coord1, coord2) {
  const R = 6371; // Radio Tierra km
  const dLat = (coord2.lat - coord1.lat) * Math.PI / 180;
  const dLon = (coord2.lon - coord1.lon) * Math.PI / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(coord1.lat * Math.PI / 180) * Math.cos(coord2.lat * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

const input = items[0].json;
const cliente = getLatLngFromUrl(input.cliente_url);

let resultados = input.agencias.map(a => {
  const agenciaCoord = getLatLngFromUrl(a.url);
  const distancia = haversineDistance(cliente, agenciaCoord);
  return { ...a, distancia_km: distancia };
});

resultados.sort((a, b) => a.distancia_km - b.distancia_km);
const masCercanas = resultados.filter(a => a.distancia_km - resultados[0].distancia_km < 1);

return [
