          ? `El concesionario más cercano es ${masCercanas[0].nombre}, a ${masCercanas[0].distancia_km.toFixed(2)} km.`
          : `Los concesionarios más cercanos son:\n${masCercanas.map(a => `- ${a.nombre} (${a.distancia_km.toFixed(2)} km)`).join("\n")}`
    }
  }
];

