    msg0.content,
    body.message,
    data.message,
    getByPath(data, 'payload.message')
  );

  // --- Distancia (acepta string u objeto con .mensaje) ---
  const distancia = firstTruthy(
    getByPath(data, 'distancia.mensaje'),
    data.distancia,
    meta.distancia
  );

  // --- Meta ---
