const WORK_START_TIME = '09:00:00'; // Configurable work start time (24-hour format)
const WORK_END_TIME_WEEKDAY = '18:00:00'; // Configurable work end time for weekdays
const WORK_END_TIME_SATURDAY = '12:00:00'; // Configurable work end time for Saturday
const TIMEZONE = 'America/Bogota'; // Configurable timezone
const TIMEZONE_OFFSET = '-05:00'; // Configurable timezone offset (must match TIMEZONE)

const busyEvents = items.map(item => item.json);

// Check if input is empty or contains only empty objects
if (busyEvents.length === 0 || (busyEvents.length === 1 && Object.keys(busyEvents[0]).length === 0)) {
  return [{ json: { message: "available" } }];
}

const eventsByDate = {};
busyEvents.forEach(event => {
  // Skip empty or invalid events
  if (!event.start || !event.end) return;
  const date = event.start.slice(0, 10);
  if (!eventsByDate[date]) {
    eventsByDate[date] = [];
  }
  eventsByDate[date].push({ start: event.start, end: event.end });
});

function formatWithOffset(ms) {
  const options = {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: TIMEZONE
  };
  const formatter = new Intl.DateTimeFormat('en-US', options);
  const parts = formatter.formatToParts(new Date(ms));
  const map = {};
  parts.forEach(p => {
    map[p.type] = p.value;
  });
  return `${map.year}-${map.month}-${map.day}T${map.hour}:${map.minute}:${map.second}${TIMEZONE_OFFSET}`;
}

const slots = [];

for (const date in eventsByDate) {
  const [year, month, day] = date.split('-').map(Number);
  const dt = new Date(Date.UTC(year, month - 1, day));
  const dayOfWeek = dt.getUTCDay();
  if (dayOfWeek === 0) continue;

  const workStartStr = `${date}T${WORK_START_TIME}${TIMEZONE_OFFSET}`;
  const workEndStr = `${date}T${dayOfWeek === 6 ? WORK_END_TIME_SATURDAY : WORK_END_TIME_WEEKDAY}${TIMEZONE_OFFSET}`;
  const workStartMS = new Date(workStartStr).getTime();
  const workEndMS = new Date(workEndStr).getTime();

  const busies = eventsByDate[date];
  let busyIntervals = [];
  busies.forEach(event => {
    let startMS = new Date(event.start).getTime();
    let endMS = new Date(event.end).getTime();
    if (endMS <= workStartMS || startMS >= workEndMS) return;
    startMS = Math.max(startMS, workStartMS);
    endMS = Math.min(endMS, workEndMS);
    busyIntervals.push({ startMS, endMS });
  });

  busyIntervals.sort((a, b) => a.startMS - b.startMS);

  const merged = [];
  busyIntervals.forEach(busy => {
    if (merged.length === 0 || merged[merged.length - 1].endMS < busy.startMS) {
      merged.push(busy);
    } else {
      merged[merged.length - 1].endMS = Math.max(merged[merged.length - 1].endMS, busy.endMS);
    }
  });

  let prevEndMS = workStartMS;
  merged.forEach(busy => {
    addSlotsToArray(prevEndMS, busy.startMS);
    prevEndMS = busy.endMS;
  });
  addSlotsToArray(prevEndMS, workEndMS);

  function addSlotsToArray(gapStartMS, gapEndMS) {
    const slotDurationMS = 30 * 60 * 1000;
    if (gapEndMS - gapStartMS < slotDurationMS) return;
    let currentStartMS = gapStartMS;
    while (currentStartMS + slotDurationMS <= gapEndMS) {
      const currentEndMS = currentStartMS + slotDurationMS;
      slots.push({
        start: formatWithOffset(currentStartMS),
        end: formatWithOffset(currentEndMS),
        duration: 30
      });
      currentStartMS = currentEndMS;
    }
  }
}

return slots.map(slot => ({ json: slot }));
